package com.gymmind.workout.api;
import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import com.gymmind.workout.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/v1/workout-plans") public class WorkoutPlanController { private final WorkoutPlanService service; private final CurrentActorProvider actors; public WorkoutPlanController(WorkoutPlanService s,CurrentActorProvider a){service=s;actors=a;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<WorkoutPlanView> create(@Valid @RequestBody Request r){return ApiResponse.success(service.create(actors.requireCurrent(),r.toCommand()));} @GetMapping("/{id}") public ApiResponse<WorkoutPlanView> find(@PathVariable Long id){return ApiResponse.success(service.find(actors.requireCurrent(),id));}
 public record Request(@NotNull Long memberId,Long coachId,@NotBlank String name,@NotBlank String goal,@NotNull LocalDate startDate,@NotNull LocalDate endDate,@NotBlank String description,@NotEmpty List<RequestItem> items){CreateWorkoutPlanCommand toCommand(){return new CreateWorkoutPlanCommand(null,memberId,coachId,name,goal,startDate,endDate,description,items.stream().map(RequestItem::toCommand).toList());}} public record RequestItem(@NotNull Long exerciseId,@Min(1)@Max(7) int dayOfWeek,@Min(1) int sets,@Min(1) int reps,@Min(0) int restSeconds,@Min(0) double weight,String notes){WorkoutPlanItemCommand toCommand(){return new WorkoutPlanItemCommand(exerciseId,dayOfWeek,sets,reps,restSeconds,weight,notes);}}
}
